	@Test
	void testContainsAll() {
		// 1. Create a list and add some elements
		LinkedList<Integer> list = new LinkedList<>();
		for (int i = 0; i < 5; i++) {
			list.add(i);
		}
		
		// 2. Create a collection that is a subset of the list
		List<Integer> subset = Arrays.asList(1, 2, 3);
		
		// 3. Assert that the list contains all elements of the subset
		assertTrue(list.containsAll(subset));
		
		// 4. Create a collection that has an element not in the list
		List<Integer> notSubset = Arrays.asList(1, 2, 6);
		
		// 5. Assert that the list does not contain all elements of this collection
		assertFalse(list.containsAll(notSubset));
	}

