	/**
	 * Test the {@code removeAll(Collection<?> c)} method
	 */
	@Test
	void testRemoveAll() {
		// 1. Create a list and add some elements
		LinkedList<Integer> list = new LinkedList<>();
		for (int i = 0; i < 10; i++) {
			list.add(i);
		}
		
		// 2. Create a collection of elements to remove
		List<Integer> toRemove = Arrays.asList(2, 4, 6, 8);
		
		// 3. Remove all elements of the collection from the list
		assertTrue(list.removeAll(toRemove));
		
		// 4. Assert that the list no longer contains the removed elements
		for (Integer elem : toRemove) {
			assertFalse(list.contains(elem));
		}
		
		// 5. Assert that the size of the list has decreased by the size of the collection
		assertEquals(6, list.size());
		
		// 6. Attempt to remove elements not in the list and assert that it returns false
		List<Integer> notInList = Arrays.asList(10, 11);
		assertFalse(list.removeAll(notInList));
	}

